-- CPF R6 V106 persistent data-quality provider schema
-- vendor=mariadb; logicalDatabase=cpfDB
ALTER TABLE CPF_DATA_QUALITY_RULE ADD COLUMN IF NOT EXISTS PARAMETERS_PAYLOAD LONGBLOB NULL;
ALTER TABLE CPF_DATA_QUALITY_QUARANTINE ADD COLUMN IF NOT EXISTS VIOLATION_PAYLOAD LONGBLOB NULL;
CREATE TABLE IF NOT EXISTS CPF_DATA_QUALITY_OPERATION (
  OPERATION_ID VARCHAR(160) NOT NULL,
  OPERATION_TYPE VARCHAR(64) NOT NULL,
  QUARANTINE_ID VARCHAR(64) NOT NULL,
  COMMAND_FINGERPRINT CHAR(64) NOT NULL,
  RESULT_PAYLOAD LONGBLOB NOT NULL,
  ACTOR_ID VARCHAR(64) NOT NULL,
  ACTION_REASON VARCHAR(1000) NOT NULL,
  CREATED_AT DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (OPERATION_ID),
  CONSTRAINT FK_CPF_DQ_OPERATION_QUARANTINE FOREIGN KEY (QUARANTINE_ID) REFERENCES CPF_DATA_QUALITY_QUARANTINE(QUARANTINE_ID),
  CONSTRAINT CK_CPF_DQ_OPERATION_HASH CHECK (CHAR_LENGTH(COMMAND_FINGERPRINT)=64),
  KEY IX_CPF_DQ_OPERATION_TARGET (QUARANTINE_ID, OPERATION_TYPE, CREATED_AT)
);
